mapper.select:
/* 후보정용어관리 (8060) */ /* AdminWordCorrectionMapper.selectListTotCnt */ SELECT COUNT(*) AS totcnt FROM CSPD117TI A LEFT JOIN (SELECT AI_INPT_INTF_ITM_NM ,AI_INPT_GRP_CD ,AI_INPT_CMN_CD_NM FROM CSPD112TI WHERE AI_INPT_GRP_CD IN ('241', '242') AND AI_INPT_INTF_ITM_NM != '110'
UNION ALL
SELECT AI_INPT_INTF_ITM_NM ,AI_INPT_GRP_CD ,AI_INPT_CMN_CD_NM FROM CSPD112TI WHERE AI_INPT_GRP_CD IN ('241', '242') AND AI_INPT_INTF_ITM_NM = '110' AND ROWNUM = 1) B ON A.AI_INPT_GRP_CD = B.AI_INPT_INTF_ITM_NM WHERE 1=1
AND B.AI_INPT_GRP_CD = #{inptAtmcBizDscd}
AND A.AI_INPT_GRP_CD = #{inptAtmcBizDscd}
AND A.AI_INPT_GRP_CD = #{schInptItem}
AND AI_INPT_WORD_TXT LIKE '%'||TRIM(UPPER(#{schText1}))||'%'

/* 후보정용어관리 (8060) */ /* AdminWordCorrectionMapper.selectSanctionList */ SELECT A.AI_INPT_INTF_ITM_NM ,A.AI_INPT_GRP_CD ,'('|| CASE WHEN A.AI_INPT_INTF_ITM_NM = '110' THEN '공통' WHEN A.AI_INPT_GRP_CD = '241' THEN '수입' WHEN A.AI_INPT_GRP_CD = '242' THEN '수출' END ||') '||A.AI_INPT_CMN_CD_NM AS AI_INPT_CMN_CD_NM FROM ( SELECT AI_INPT_INTF_ITM_NM ,AI_INPT_GRP_CD ,AI_INPT_CMN_CD_NM FROM CSPD112TI WHERE AI_INPT_GRP_CD IN ('241', '242') AND AI_INPT_INTF_ITM_NM != '110'
UNION ALL
SELECT AI_INPT_INTF_ITM_NM ,AI_INPT_GRP_CD ,AI_INPT_CMN_CD_NM FROM CSPD112TI WHERE AI_INPT_GRP_CD IN ('241', '242') AND AI_INPT_INTF_ITM_NM = '110' AND ROWNUM = 1 ) A WHERE 1=1
AND AI_INPT_GRP_CD = #{inptAtmcBizDscd} AND AI_INPT_INTF_ITM_NM != '110'
AND AI_INPT_INTF_ITM_NM = #{inptAtmcBizDscd}

/* 후보정용어관리 (8060) */
/* AdminWordCorrectionMapper.selectWordDuplicationCheck */
SELECT COUNT(*) FROM CSPD117TI
 WHERE AI_INPT_GRP_CD = #{aiInptGrpCd}
   AND AI_INPT_WORD_TXT = #{aiInptWordTxt}

mapper.update:
/* 후보정용어관리 (8060) */
/* AdminWordCorrectionMapper.updateWord */
UPDATE CSPD117TI 
   SET AI_INPT_WORD_TXT = TRIM(UPPER(#{aiInptWordTxt})),
	   TRN_LOG_SRNO = #{trnLogSrno},
	   LST_DB_CHG_ID = #{lstDbChgId},
	   LST_DB_CHG_DTM = (SELECT TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISSFF6') FROM DUAL)
 WHERE AI_INPT_WORD_SRNO = #{aiInptWordSrno}
   AND AI_INPT_GRP_CD = #{aiInptGrpCd}

mapper.delete:
		/* 후보정용어관리 (8060) */
		/* AdminWordCorrectionMapper.deleteWord */
		DELETE FROM CSPD117TI
	  		  WHERE AI_INPT_WORD_SRNO = #{aiInptWordSrno}
   				AND AI_INPT_GRP_CD = #{aiInptGrpCd}
